//! ADM1 CSTR parity against `src/sim/adm1.ts`.
//!
//! Fixture: seed digester feed, V=1000 m3, Q=100 m3/h, 0.5 h steps, 48 h.
//! Golden generated by the TypeScript oracle on 2026-11-25.

use aquapilot_core::adm1::{Component, Output, PARAMS, State, StepOptions, empty_state, step_adm1};

const EXPECTED: [f64; 27] = [
    0.21929378140629469,
    0.05,
    27.87616249912258,
    2.3964686818844414,
    2.3964686818844414,
    30.378464927307604,
    45.409189874479104,
    5e-05,
    26.82522760683351,
    70.72437883304917,
    50.0,
    20.19699194456374,
    99.64070071319492,
    9.748709710777293,
    9.748709710777293,
    5.86207003444531,
    15.897137263158367,
    14.321495142355092,
    5.048946043533252,
    5.269163780123519,
    5.091103402349308,
    10.120470838030515,
    15.673262367209139,
    50.0,
    4.145833333333333e-05,
    19.660537668207045,
    29.275621166950764,
];

fn feed() -> State {
    let mut s = empty_state();
    for (c, v) in [
        (Component::SSu, 20.0),
        (Component::SAa, 10.0),
        (Component::SFa, 5.0),
        (Component::SVa, 5.0),
        (Component::SBu, 5.0),
        (Component::SPro, 5.0),
        (Component::SAc, 20.0),
        (Component::SH2, 0.01),
        (Component::SCh4, 0.1),
        (Component::SIC, 100.0),
        (Component::SIN, 50.0),
        (Component::SI, 20.0),
        (Component::Xc, 100.0),
        (Component::Xch, 50.0),
        (Component::Xpr, 50.0),
        (Component::Xli, 30.0),
        (Component::Xsu, 10.0),
        (Component::Xaa, 10.0),
        (Component::Xfa, 5.0),
        (Component::Xc4, 5.0),
        (Component::Xpro, 5.0),
        (Component::Xac, 10.0),
        (Component::Xh2, 5.0),
        (Component::XI, 50.0),
    ] {
        s.set(c, v);
    }
    s
}

#[test]
fn adm1_48h_matches_ts_golden() {
    let inf = feed();
    let mut state = inf;
    let mut last: Output = step_adm1(
        &state,
        &inf,
        &PARAMS,
        StepOptions {
            volume: 1000.0,
            flow: 100.0,
            dt_hours: 0.5,
        },
    );
    state = last.state;
    for _ in 1..96 {
        last = step_adm1(
            &state,
            &inf,
            &PARAMS,
            StepOptions {
                volume: 1000.0,
                flow: 100.0,
                dt_hours: 0.5,
            },
        );
        state = last.state;
    }
    for (i, want) in EXPECTED.iter().enumerate() {
        let got = state.v[i];
        let tol = 64.0 * f64::EPSILON * want.abs().max(1.0);
        assert!(
            (got - want).abs() <= tol,
            "component {i}: got {got} want {want} tol {tol}"
        );
    }
    assert!((last.methane_rate - 2.2344576736153865).abs() <= 1e-12);
    assert!((last.methane_fraction - 0.40175856626167267).abs() <= 1e-12);
    assert!((last.ph - 7.143338687189809).abs() <= 1e-12);
    assert!(last.inhibited);
}
